#!/usr/bin/env node
// Phase 08 / Pass 1: generates scripts/audit/props/__tests__/<slug>.props.test.tsx
// (one thin file per renderable component slug) from the machine-readable
// prop model (scripts/audit/lib/prop-model.mjs). All assertion logic lives
// in the hand-written scripts/audit/props/test-driver.tsx — a generated file
// only imports it and hands it that slug's slice of the model, so
// regeneration never has to re-derive assertion strategy per prop kind.
//
// Usage: node scripts/audit/gen-prop-tests.mjs
// Writes scripts/audit/props/model.json and scripts/audit/props/__tests__/*.props.test.tsx.
import { mkdir, writeFile, rm, readdir } from 'node:fs/promises';
import path from 'node:path';
import { buildPropModel } from './lib/prop-model.mjs';

const ROOT = process.cwd();
const PROPS_DIR = path.join(ROOT, 'scripts', 'audit', 'props');
const TESTS_DIR = path.join(PROPS_DIR, '__tests__');
const RESULTS_DIR = path.join(PROPS_DIR, '.results');

function testFileSource(slug) {
  return `// AUTO-GENERATED by scripts/audit/gen-prop-tests.mjs from scripts/audit/props/model.json.
// Do not hand-edit — rerun the generator. All assertion logic lives in
// ../test-driver (scripts/audit/props/test-driver.tsx).
import model from '../model.json';
import { runComponentPropTests } from '../test-driver';

const componentModel = model.components.find((c) => c.slug === ${JSON.stringify(slug)});

if (!componentModel) {
  test.skip(${JSON.stringify(`${slug}: no model entry`)}, () => {});
} else {
  runComponentPropTests(${JSON.stringify(slug)}, componentModel);
}
`;
}

async function main() {
  const model = await buildPropModel(ROOT);

  await mkdir(PROPS_DIR, { recursive: true });
  await writeFile(path.join(PROPS_DIR, 'model.json'), JSON.stringify(model, null, 2), 'utf8');

  // Fresh result set every regeneration/run cycle.
  await rm(RESULTS_DIR, { recursive: true, force: true });
  await mkdir(RESULTS_DIR, { recursive: true });

  // Clear previously generated test files (a slug removed from the docs site
  // between runs must not leave a stale generated file behind).
  await mkdir(TESTS_DIR, { recursive: true });
  for (const f of await readdir(TESTS_DIR)) {
    if (f.endsWith('.props.test.tsx')) await rm(path.join(TESTS_DIR, f));
  }

  let written = 0;
  for (const c of model.components) {
    const hasRenderable = (c.propTypes || []).some((pt) => pt.isRenderable);
    if (!hasRenderable) continue;
    await writeFile(path.join(TESTS_DIR, `${c.slug}.props.test.tsx`), testFileSource(c.slug), 'utf8');
    written += 1;
  }

  console.log(`Prop model: ${model.totals.components} components, ${model.totals.propTypes} prop types, ${model.totals.ownProps} own props.`);
  console.log('By kind:', model.totals.byKind);
  console.log(`Generated ${written} test files under ${path.relative(ROOT, TESTS_DIR)}/`);
}

main().catch((err) => {
  console.error(err);
  process.exitCode = 1;
});
